(function(){
'use strict';
// TEST238 — diagonal multi-color stress fallback.
// Keep TEST236 RLE where it fits. For dense-color maps where the RLE plan
// does not fit, reuse the existing full Color RAM commit routine.
// The shadow at $0C00 is already generated by diag_colors221 in main.
// Avoid TEST203's 1024-cell compare/pack and its variable-index IRQ writes.
// This changes ONLY the diagonal, fast-row, non-uniform, no-group fallback.
// The original code and its tables remain available for other routes.
var E=window.RICO_TEST196_DIAGONAL;
if(!E||typeof E.build!=='function')return;
var previous=E.build,NL='\n';
E.build=function(d){
 var asm=previous(d),base=window.RICO_TEST236_LAST_BUILD;
 var info={selected:false,version:238,mode:'original/TEST236',reason:''};
 if(!d||!d.fastRows){info.reason='non-fastRows: preserve fallback';}
 else if(d.uniformColor){info.reason='uniform color: no update needed';}
 else if(d.group){info.reason='group mode: unchanged';}
 else if(base&&base.selected){info.reason='TEST236 RLE fast path selected';}
 else {
  var prep=NL+' jsr prepare_sparse_colors203',
      irq=NL+' jsr commit_sparse_colors203',
      shadow=NL+' jsr diag_colors221',
      copier=NL+'commit_colors199'+NL;
  if(asm.split(prep).length!==2||asm.split(irq).length!==2||
     asm.split(shadow).length!==2||!asm.includes(copier)){
    throw Error('TEST238: unexpected diagonal fallback anchors; not patching');
  }
  // Preparation is already done by diag_colors221. We only bypass
  // expensive changed-cell comparison/index packing and commit direct.
  asm=asm.replace(prep,'').replace(irq,NL+' jsr commit_colors199');
  info={selected:true,version:238,mode:'full-Color-RAM-direct',
    colorPreparation:'diag_colors221 -> $0C00',
    irqCommit:'existing commit_colors199 -> $D800',
    changed:'only dense-color TEST236 fallback',
    screenCopy:'unchanged TEST221',borders:'unchanged',
    caveat:'IRQ now writes all 1024 Color RAM slots per boundary'};
 }
 window.RICO_TEST238_LAST_BUILD=info;
 console.log('[TEST238 DIAGONAL COLOR FALLBACK]',info);
 return asm;
};
window.RICO_TEST238_DIAGONAL={version:238,previous:previous};
})();
